    easier: ["على الظهر أو الجنب (بلا ثقل الذراع)، ومساعدةٌ أكثر.", "Lying on the back or side (gravity removed), with more help."],
    harder: ["بلا مساعدة، ولعبةٌ أثقل، ومن طاولةٍ أخفض.", "No help, a heavier toy, and from a lower table."],
    stopIf: ["خطرُ الشرقة ⟵ طعامٌ يناسب العمرَ وحده وتحت النظر؛ التعبُ أو الضيق ⟵ توقّفوا.", "Choking risk → age-appropriate food only, under watch; tiredness or fussing → stop."],
    equipment: ["عضّاضة، وطعامٌ طريٌّ يُمسك بالأصابع، وألعاب.", "A teether, soft finger food, and toys."],
    doseNote: ["٥–١٠ محاولات، مرّاتٍ في اليوم في اللعب والطعام (اقتراحٌ لا جرعةٌ مجرَّبة)؛ والاختبارُ نفسُه يجريه الأخصائيّ في الشهر التاسع (Cawthorn 2023).", "5–10 tries, several times a day in play and at meals (a proposal, not a tested dose); the test itself is done by the specialist at nine months (Cawthorn 2023)."],
    images: [{ key: "bpbi-hand-to-mouth-elbow-flexion-1", ar: "طفلٌ صغير جالسٌ على فراش يرفع لعبةً خضراء إلى فمه والمرفقان مثنيّان، ويدُ بالغٍ تسند خلفَ كتفه ويدٌ أخرى تساعده عند الساعد، والوجوهُ مموّهة", en: "A toddler sitting on a mat brings a green toy up to the mouth with the elbows bent; one adult's hand steadies the back of the shoulder and another helps at the forearm; faces blurred", search: "cookie test hand to mouth infant brachial plexus elbow flexion arm adducted" }],
